import json # Read only frozen training and independent numerical evaluation evidence.
from pathlib import Path # Keep diagnostic figures beside their source measurements.
import numpy as np # Position actual model-comparison bars and convert relative errors to percentages.
import matplotlib # Render static scientific diagnostics without synthesizing finite-element contours.
matplotlib.use('Agg') # Use a reproducible headless plotting backend.
import matplotlib.pyplot as plt # Plot measured displacement errors, full residuals and convergence histories.
from unified_graph import OUT,FAMILIES # Use the same registered experiment output and family order.
def main(): # Create reviewable plots only after every actual numerical experiment is complete.
    summary=json.loads((OUT/'summary.json').read_text());selected={x['mode']:x for x in summary['experiments']};baseline_seed=selected['all_families']['selected_seed'];paths=[OUT/'all_families'/f'seed_{baseline_seed}',OUT/'refined_all_families',OUT/'physics_all_families'];labels=['Shared baseline','Geometry + difference supervision','Full Ku-f physical training'];colors=['#8294ad','#287ca5','#b6553f'];evaluations=[json.loads((p/'evaluation.json').read_text()) for p in paths] # Compare validation-selected actual weights across increasingly substantive training attempts.
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'white'});fig,axes=plt.subplots(2,2,figsize=(15,10));x=np.arange(len(FAMILIES)) # Use consistent readable scientific figure styling.
    for i,(evaluation,label,color) in enumerate(zip(evaluations,labels,colors)): # Keep exact denominators and no hidden physical correction.
        rows={r['family']:r for r in evaluation['summary']};axes[0,0].bar(x+(i-1)*.25,[100*rows[f]['mean_relative_L2'] for f in FAMILIES],width=.24,label=label,color=color);axes[0,1].bar(x+(i-1)*.25,[rows[f]['max_full_equilibrium_relative'] for f in FAMILIES],width=.24,color=color) # Report measured full-field displacement errors and worst unreduced force residuals.
    for ax in axes[0]:ax.set_xticks(x,FAMILIES,rotation=25,ha='right');ax.grid(axis='y',alpha=.2) # Keep per-family model comparisons legible.
    axes[0,0].axhline(5,color='#333333',linestyle='--',linewidth=1,label='5% research error gate');axes[0,0].set_ylabel('Mean relative displacement error (%)');axes[0,0].set_title('Development test: 8 geometry/load cases per family');axes[0,0].legend(fontsize=8);axes[0,1].set_yscale('log');axes[0,1].axhline(.05,color='#333333',linestyle='--',linewidth=1);axes[0,1].set_ylabel('Maximum ||K u - f|| / ||f||, free DOFs');axes[0,1].set_title('Raw physical residual: no numerical post-correction') # Keep physical failure visible even when displacement improves.
    for mode,style in [('all_families','-'),('leave_deck_out','--')]: # Show every random initialization instead of a selected favourable trajectory.
        for seed,color in zip([17,41],['#287ca5','#b6553f']): # Retain independently trained shared-model seeds.
            history=json.loads((OUT/mode/f'seed_{seed}'/'history.json').read_text())['history'];axes[1,0].plot([h['epoch'] for h in history],[100*h['validation_relative_L2_sampled'] for h in history],style,color=color,label=f'{mode}, seed {seed}') # Plot actual fixed-validation checkpoint observations.
    history=json.loads((OUT/'refined_all_families/history.json').read_text())['history'];axes[1,0].plot([h['epoch']+300 for h in history],[100*h['validation_relative'] for h in history],color='#36956f',label='refinement from seed 17');axes[1,0].set_xlabel('Optimization epoch (refinement begins at 300)');axes[1,0].set_ylabel('Sampled validation relative error (%)');axes[1,0].set_title('Optimization evidence: fixed validation selection');axes[1,0].legend(fontsize=8);axes[1,0].grid(alpha=.2) # Distinguish continued optimization from a restarted task or untrained proposal.
    unseen=selected['leave_deck_out'];unseen_rows=[s for s in unseen['seeds']];names=[f"Seed {s['seed']}" for s in unseen_rows];values=[100*s['complete_metrics']['entirely_unseen_structural_type']['mean_relative_L2'] for s in unseen_rows];axes[1,1].bar(names,values,color=['#287ca5','#b6553f']);axes[1,1].axhline(5,color='#333333',linestyle='--',linewidth=1);axes[1,1].set_ylabel('Mean unseen-type displacement error (%)');axes[1,1].set_title('Deck absent from fitting AND validation: all 56 cases');axes[1,1].grid(axis='y',alpha=.2) # Show actual type extrapolation failure without relabeling it successful universality.
    for i,value in enumerate(values):axes[1,1].text(i,value,f'{value:.1f}%',ha='center',va='bottom') # Label actual held-out topology errors directly.
    fig.suptitle('Shared variable-topology operator: trained and tested; engineering release HOLD',fontsize=15);fig.tight_layout();fig.savefig(OUT/'unified_experiment_evidence.png',dpi=180);plt.close(fig) # Save a standalone artifact with transparent qualification status.
    confirmation=summary['independent_confirmation'];fig,axes=plt.subplots(1,2,figsize=(12,4.5));errors=[100*confirmation['families'][f]['mean_relative_L2'] for f in FAMILIES];residuals=[confirmation['families'][f]['max_full_equilibrium_relative'] for f in FAMILIES];axes[0].bar(FAMILIES,errors,color='#287ca5');axes[1].bar(FAMILIES,residuals,color='#b6553f');axes[0].axhline(5,color='#333333',linestyle='--');axes[1].axhline(.05,color='#333333',linestyle='--');axes[0].set_ylabel('Mean displacement error (%)');axes[1].set_ylabel('Maximum full equilibrium residual');axes[1].set_yscale('log') # Keep first-use architecture confirmation distinct from repeatedly inspected development tests.
    for ax in axes:ax.tick_params(axis='x',rotation=25);ax.grid(axis='y',alpha=.2) # Preserve exact family coverage and readable labels.
    fig.suptitle('New unified-architecture confirmation: fixed final weights, 32 cases, no adaptation');fig.tight_layout();fig.savefig(OUT/'unified_confirmation_evidence.png',dpi=180);plt.close(fig) # Save actual independent confirmation evidence without changing any model choice.
if __name__=='__main__':main() # Render only frozen evidence and never trigger training from the plotting script.
